import React, { useState, useEffect } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, LabelList, Cell } from "recharts";
import { motion, AnimatePresence } from "framer-motion";

// Αυτό το αρχείο είναι μια αυτόνομη εφαρμογή React για την παρακολούθηση εκλογών.
// Χρησιμοποιεί τη μέθοδο αναλογικής εκπροσώπησης και περιλαμβάνει επιλογές για
// τη στρογγυλοποίηση του μέτρου, με ένα σύγχρονο UI κατασκευασμένο με Tailwind CSS και Framer Motion.

// --- Ελαφριές δοκιμές κατανομής (εκτελούνται μία φορά σε περιβάλλον dev/οποιοδήποτε) ---
// Αυτές οι διαβεβαιώσεις διασφαλίζουν ότι η βασική λογική κατανομής των εδρών είναι σωστή.
function runAllocationTests() {
  const mk = (arr) => arr.map(v => ({ votes: v }));
  const props = (arr, s, tieRule, onTie) => proportional({ parties: mk(arr), seats: s, tieBreakingRule: tieRule, showTieModal: onTie });

  // Ίση κατανομή
  console.assert(JSON.stringify(props([1000, 1000, 1000], 9, 'least_seats', () => {}).seats) === JSON.stringify([3, 3, 3]), "Proportional equal split failed");

  // Απλή αναλογία
  console.assert(JSON.stringify(props([600, 300, 100], 10, 'least_seats', () => {}).seats) === JSON.stringify([6, 3, 1]), "Proportional 60/30/10 failed");

  // Ακραία περίπτωση μεγαλύτερου υπολοίπου
  console.assert(JSON.stringify(props([34, 33, 33], 10, 'least_seats', () => {}).seats) === JSON.stringify([4, 3, 3]), "Proportional 34/33/33 failed");
}

// --- Μέθοδος Αναλογικής Κατανομής (async) ---
// Αυτός ο αλγόριθμος είναι πλέον async για να χειρίζεται τη διαδραστική επιλογή του χρήστη.
// Επιστρέφει ένα αντικείμενο με τις τελικές έδρες και, εάν υπήρξε, το αποτέλεσμα της ισοψηφίας.
async function proportional({ parties, seats, tieBreakingRule, showTieModal }) {
  const total = parties.reduce((s, p) => s + Number(p.votes || 0), 0);
  if (!seats || seats < 0) return { seats: parties.map(() => 0) };
  if (total === 0) return { seats: parties.map(() => 0) };
  const exact = parties.map(x => (Number(x.votes || 0) / total) * seats);
  const floor = exact.map(x => Math.floor(x));
  let assigned = floor.reduce((s, x) => s + x, 0);
  const rem = exact.map((x, i) => ({ i, r: x - floor[i] })).sort((a, b) => b.r - a.r);
  const res = [...floor];

  let tieResult = null;
  let k = 0;
  while (assigned < seats) {
    if (k >= rem.length) {
      break; // No more parties to assign seats to
    }
    let tiedCandidates = [rem[k]];
    let nextIndex = k + 1;
    while (nextIndex < rem.length && rem[nextIndex].r === rem[k].r) {
      tiedCandidates.push(rem[nextIndex]);
      nextIndex++;
    }

    let winnerIndex;
    if (tiedCandidates.length > 1) {
      // Logic for resolving ties
      let tiedPartyNames = tiedCandidates.map(c => parties[c.i].name);
      let winnerName;
      let manualChoiceNeeded = false;

      // Check for identical votes among tied candidates
      const tiedVotes = new Set(tiedCandidates.map(c => parties[c.i].votes));
      if (tiedVotes.size === 1) {
        // All tied parties have the exact same vote count
        manualChoiceNeeded = true;
      }

      if (tieBreakingRule === 'Στρίψιμο νομίσματος' || manualChoiceNeeded) {
        // Show modal for manual choice
        const chosenPartyFromModal = await showTieModal({ parties: tiedCandidates.map(c => parties[c.i]), tieBreakingRule, manualOverride: manualChoiceNeeded });
        const winnerParty = parties.find(p => p.name === chosenPartyFromModal.name);
        winnerIndex = parties.indexOf(winnerParty);
        winnerName = winnerParty.name;
      } else {
        // Resolve tie automatically based on the rule
        let preDefinedWinner;
        switch (tieBreakingRule) {
          case 'least_seats':
            tiedCandidates.sort((a, b) => res[a.i] - res[b.i]);
            preDefinedWinner = tiedCandidates[0];
            break;
          case 'most_seats':
            // Correct logic to prioritize the party with the most already-assigned seats
            tiedCandidates.sort((a, b) => res[b.i] - res[a.i]);
            preDefinedWinner = tiedCandidates[0];
            break;
          default:
            preDefinedWinner = tiedCandidates[0];
            break;
        }
        winnerIndex = preDefinedWinner.i;
        winnerName = parties[winnerIndex].name;
      }

      // Record the tie-breaking result
      tieResult = {
        tiedParties: tiedPartyNames,
        winnerName,
        ruleUsed: manualChoiceNeeded ? 'Manual Override' : tieBreakingRule,
        message: 'Επιλύθηκε με επιλογή του χρήστη ή προκαθορισμένο κανόνα.'
      };

    } else {
      winnerIndex = rem[k].i;
    }

    res[winnerIndex]++;
    assigned++;
    k += tiedCandidates.length;
  }
  return { seats: res, tieResult };
}


// Κύριο component για την εφαρμογή Election Tracker
export default function App() {
  const [setup, setSetup] = useState(true);
  const [totalVotes, setTotalVotes] = useState(0);
  const [totalSeats, setTotalSeats] = useState(0);
  const [parties, setParties] = useState([
    { name: "ΠΚΣ", color: "#ff0000", votes: 0 },
    { name: "ΔΑΠ", color: "#0000ff", votes: 0 },
    { name: "ΠΑΣΠ", color: "#008000", votes: 0 },
    { name: "ΕΑΑΚ", color: "#000000", votes: 0 },
    { name: "ATTACK", color: "#ffc0cb", votes: 0 }
  ]);
  const [voidVotes, setVoid] = useState(0);
  const [blankVotes, setBlank] = useState(0);
  const [quotaRounding, setQuotaRounding] = useState('none');
  const [decimalPlaces, setDecimalPlaces] = useState(2);
  const [tieBreakingRule, setTieBreakingRule] = useState('least_seats');
  const [seatsNow, setSeatsNow] = useState(parties.map(() => 0));
  const [isCalculating, setIsCalculating] = useState(false);
  const [modal, setModal] = useState(null);
  const [isFinalResult, setIsFinalResult] = useState(false);

  useEffect(() => { runAllocationTests(); }, []);

  const randColor = () => `hsl(${Math.floor(Math.random() * 360)} 70% 55%)`;
  const updateParty = (i, key, val) => {
    setParties(ps => ps.map((p, j) => j === i ? { ...p, [key]: val } : p));
  };
  const addParty = () => setParties(p => [...p, { name: `Ψηφοδέλτιο ${p.length + 1}`, color: randColor(), votes: 0 }]);
  const removeParty = (i) => setParties(ps => ps.filter((_, j) => j !== i));

  // The useEffect now has a cleanup function to prevent race conditions.
  useEffect(() => {
    if (!setup) {
      let isMounted = true; // Flag to track if the component is still mounted

      const calculate = async () => {
        setIsCalculating(true);
        // Function to return a Promise that resolves when the user makes a modal choice
        const showTieModalCallback = ({ parties: tiedParties, tieBreakingRule, manualOverride }) => {
          return new Promise((resolve) => {
            setModal({
              isOpen: true,
              title: "Ισοψηφία για έδρα!",
              message: manualOverride ? "Ψηφοδέλτια με ίδιο αριθμό ψήφων και υπολοίπου. Επιλέξτε ποιοθα πάρει την έδρα." : "Επιλέξτε ποιο ψηφοδέλτιο θα πάρει την επόμενη έδρα.",
              parties: tiedParties,
              isManualChoice: true,
              onResolve: (chosenParty) => {
                setModal(null);
                resolve(chosenParty); // Resolve with the full party object
              }
            });
          });
        };

        const result = await proportional({ parties, seats: totalSeats, tieBreakingRule, showTieModal: showTieModalCallback });

        // Only update state if the component is still mounted and this is the latest calculation
        if (isMounted) {
          setSeatsNow(result.seats);
          setIsCalculating(false);
        }
      };

      calculate();
      
      // Cleanup function to prevent state updates on unmounted components
      return () => {
        isMounted = false;
      };
    }
  }, [setup, parties, totalSeats, totalVotes, voidVotes, blankVotes, tieBreakingRule]);

  const counted = parties.reduce((s, p) => s + Number(p.votes || 0), 0) + voidVotes + blankVotes;
  const totalValidVotes = totalVotes - voidVotes;
  let voteQuota = totalSeats > 0 ? (totalValidVotes / totalSeats) : 0;

  useEffect(() => {
    // This effect handles the final result display based on the count
    if (counted === totalVotes && !isCalculating) {
      setIsFinalResult(true);
    } else {
      setIsFinalResult(false);
    }
  }, [counted, totalVotes, isCalculating]);

  if (quotaRounding === 'floor') {
    voteQuota = Math.floor(voteQuota);
  } else if (quotaRounding === 'ceil') {
    voteQuota = Math.ceil(voteQuota);
  } else if (quotaRounding === 'digits' && !isNaN(decimalPlaces)) {
    voteQuota = parseFloat(voteQuota.toFixed(decimalPlaces));
  }

  const securedSeats = (() => {
    if (voteQuota === 0) return parties.map(() => 0);
    return parties.map(p => Math.floor(Number(p.votes || 0) / voteQuota));
  })();

  const percent = (v, t) => t > 0 ? (v / t * 100) : 0;
  const remainingSeats = totalSeats - seatsNow.reduce((s, x) => s + x, 0);

  const containerVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.5 } },
    exit: { opacity: 0, y: -20, transition: { duration: 0.3 } }
  };

  const buttonVariants = {
    active: { scale: 1.05, boxShadow: "0 4px 10px rgba(0,0,0,0.1)" },
    inactive: { scale: 1, boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }
  };

  const Modal = ({ isOpen, title, message, parties, onResolve, isManualChoice, preDefinedWinner }) => {
    if (!isOpen) return null;

    return (
      <motion.div
        className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
      >
        <motion.div
          className="bg-white p-8 rounded-3xl shadow-xl w-full max-w-md text-center space-y-6"
          initial={{ scale: 0.9, y: 50 }}
          animate={{ scale: 1, y: 0 }}
        >
          <h3 className="text-2xl font-bold text-slate-800">{title}</h3>
          <p className="text-slate-600">{message}</p>
          {isManualChoice ? (
            <div className="flex flex-col gap-3">
              {parties.map((p, i) => (
                <button
                  key={i}
                  className="w-full px-6 py-3 rounded-full font-bold text-white shadow-md transition-all duration-300"
                  style={{ backgroundColor: p.color }}
                  onClick={() => onResolve(p)} // Pass the full party object
                >
                  {p.name}
                </button>
              ))}
            </div>
          ) : (
            <div className="flex flex-col gap-4 items-center">
              <p className="text-xl font-bold text-slate-800">Προτεινόμενο:</p>
              <div
                className="w-24 h-24 rounded-full flex items-center justify-center text-white font-bold text-lg"
                style={{ backgroundColor: preDefinedWinner?.color }}
              >
                {preDefinedWinner?.name}
              </div>
              <p className="text-xl font-bold text-slate-800">{preDefinedWinner?.name} κερδίζει την έδρα!</p>
              <button
                className="px-6 py-3 rounded-full bg-blue-600 text-white font-semibold shadow-md hover:bg-blue-700 transition-all duration-300"
                onClick={() => onResolve(preDefinedWinner)}
              >
                Εντάξει
              </button>
            </div>
          )}
        </motion.div>
      </motion.div>
    );
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-200 p-6 flex flex-col items-center font-sans text-slate-800">
      <AnimatePresence>
        {modal && <Modal {...modal} />}
      </AnimatePresence>
      <AnimatePresence mode="wait">
        {setup ? (
          <motion.div
            key="setup"
            initial="hidden"
            animate="visible"
            exit="exit"
            variants={containerVariants}
            className="w-full max-w-4xl bg-white p-8 rounded-3xl shadow-2xl space-y-8"
          >
            <h1 className="text-4xl font-extrabold text-center text-slate-900">Ρυθμίσεις εκλογών</h1>
            <div className="grid md:grid-cols-2 gap-6">
              <label className="block space-y-2">
                <span className="text-sm font-semibold text-slate-700">Σύνολο ψήφων</span>
                <input
                  className="border border-slate-300 p-3 w-full rounded-xl focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition"
                  type="number"
                  value={totalVotes}
                  onChange={e => setTotalVotes(Math.max(0, +e.target.value || 0))}
                />
              </label>
              <label className="block space-y-2">
                <span className="text-sm font-semibold text-slate-700">Σύνολο εδρών προς κατανομή</span>
                <input
                  className="border border-slate-300 p-3 w-full rounded-xl focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition"
                  type="number"
                  value={totalSeats}
                  onChange={e => setTotalSeats(Math.max(0, +e.target.value || 0))}
                />
              </label>
            </div>

            <div className="space-y-4">
              <span className="text-base font-semibold text-slate-700">Μέθοδος στρογγυλοποίησης μέτρου</span>
              <div className="flex flex-wrap gap-4 items-end">
                <motion.button
                  variants={buttonVariants}
                  animate={quotaRounding === 'none' ? 'active' : 'inactive'}
                  onClick={() => setQuotaRounding('none')}
                  className={`px-4 py-2 rounded-full font-medium transition-colors border ${quotaRounding === 'none' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                >
                  Καμία στρογγυλοποίηση
                </motion.button>
                <motion.button
                  variants={buttonVariants}
                  animate={quotaRounding === 'floor' ? 'active' : 'inactive'}
                  onClick={() => setQuotaRounding('floor')}
                  className={`px-4 py-2 rounded-full font-medium transition-colors border ${quotaRounding === 'floor' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                >
                  Προς τα κάτω
                </motion.button>
                <motion.button
                  variants={buttonVariants}
                  animate={quotaRounding === 'ceil' ? 'active' : 'inactive'}
                  onClick={() => setQuotaRounding('ceil')}
                  className={`px-4 py-2 rounded-full font-medium transition-colors border ${quotaRounding === 'ceil' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                >
                  Προς τα πάνω
                </motion.button>
                <div className="flex items-center gap-2">
                  <motion.button
                    variants={buttonVariants}
                    animate={quotaRounding === 'digits' ? 'active' : 'inactive'}
                    onClick={() => setQuotaRounding('digits')}
                    className={`px-4 py-2 rounded-full font-medium transition-colors border ${quotaRounding === 'digits' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                  >
                    Στρογγυλοποίηση σε
                  </motion.button>
                  <input
                    type="number"
                    value={decimalPlaces}
                    onChange={e => setDecimalPlaces(Math.max(0, parseInt(e.target.value) || 0))}
                    className="w-16 border border-slate-300 p-2 rounded-xl text-center focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition"
                    disabled={quotaRounding !== 'digits'}
                  />
                  <span>δεκαδικά</span>
                </div>
              </div>
            </div>

            <motion.div
              layout
              className="space-y-4"
              initial="hidden"
              animate="visible"
              transition={{ staggerChildren: 0.1 }}
            >
              <div className="text-base font-semibold text-slate-700">Ψηφοδέλτια</div>
              <AnimatePresence>
                {parties.map((p, i) => (
                  <motion.div
                    key={i}
                    layout
                    initial={{ opacity: 0, y: -20, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 20, scale: 0.95 }}
                    transition={{ duration: 0.3 }}
                    className="flex flex-col md:flex-row gap-3 items-center bg-slate-50 p-4 rounded-xl shadow-inner"
                  >
                    <input
                      className="border border-slate-300 p-3 w-full rounded-xl focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition"
                      placeholder={`Ψηφοδέλτιο ${i + 1}`}
                      value={p.name}
                      onChange={e => updateParty(i, "name", e.target.value)}
                    />
                    <input
                      aria-label="Χρώμα ψηφοδελτίου"
                      type="color"
                      className="w-full md:w-12 h-12 p-1 border-2 border-slate-300 rounded-full cursor-pointer transition"
                      value={p.color}
                      onChange={e => updateParty(i, "color", e.target.value)}
                    />
                    <button
                      className="px-6 py-3 rounded-full text-red-700 bg-red-100 border border-red-200 hover:bg-red-200 transition-all duration-300 w-full md:w-auto"
                      onClick={() => removeParty(i)}
                    >
                      Αφαίρεση
                    </button>
                  </motion.div>
                ))}
              </AnimatePresence>
              <button
                className="w-full md:w-auto px-6 py-3 rounded-full bg-blue-600 text-white font-semibold shadow-md hover:bg-blue-700 transition-all duration-300"
                onClick={addParty}
              >
                Προσθήκη ψηφοδελτίου
              </button>
            </motion.div>
            {/* Νέα Ενότητα Προχωρημένων Ρυθμίσεων */}
            <div className="space-y-4 pt-4 border-t border-slate-200">
              <span className="text-base font-semibold text-slate-700">Προχωρημένες ρυθμίσεις</span>
              <div className="flex flex-wrap gap-4 items-end">
                <span className="font-semibold text-sm text-slate-600">Σε περίπτωση ισοψηφίας υπολοίπου:</span>
                <motion.button
                  variants={buttonVariants}
                  animate={tieBreakingRule === 'Στρίψιμο νομίσματος' ? 'active' : 'inactive'}
                  onClick={() => setTieBreakingRule('Στρίψιμο νομίσματος')}
                  className={`px-4 py-2 rounded-full font-medium transition-colors border ${tieBreakingRule === 'Στρίψιμο νομίσματος' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                >
                  Η έδρα κατανέμεται με κλήρωση
                </motion.button>
                <motion.button
                  variants={buttonVariants}
                  animate={tieBreakingRule === 'least_seats' ? 'active' : 'inactive'}
                  onClick={() => setTieBreakingRule('least_seats')}
                  className={`px-4 py-2 rounded-full font-medium transition-colors border ${tieBreakingRule === 'least_seats' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                >
                  Η έδρα πάει στο ψηφοδέλτιο με τις λιγότερες ψήφους
                </motion.button>
                <motion.button
                  variants={buttonVariants}
                  animate={tieBreakingRule === 'most_seats' ? 'active' : 'inactive'}
                  onClick={() => setTieBreakingRule('most_seats')}
                  className={`px-4 py-2 rounded-full font-medium transition-colors border ${tieBreakingRule === 'most_seats' ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-100 text-slate-800 border-slate-300 hover:bg-slate-200'}`}
                >
                  Η έδρα πάει στο ψηφοδέλτιο με τις περισσότερες ψήφους
                </motion.button>
              </div>
            </div>

            <div className="flex justify-end items-center pt-4 border-t border-slate-200">
              <button
                className="px-8 py-3 rounded-full bg-emerald-600 text-white font-bold shadow-lg hover:bg-emerald-700 transition-all duration-300"
                onClick={() => setSetup(false)}
              >
                Έναρξη καταμέτρησης
              </button>
            </div>
          </motion.div>
        ) : (
          <motion.div
            key="counting"
            initial="hidden"
            animate="visible"
            exit="exit"
            variants={containerVariants}
            className="w-full max-w-5xl bg-white p-8 rounded-3xl shadow-2xl space-y-8"
          >
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
              <div>
                <div className="text-3xl font-bold">Καταμέτρηση ψήφων</div>
                <div className="text-sm text-slate-600">
                  <span className="font-semibold">Καταμετρημένα:</span> {counted} / {totalVotes} ψηφοδέλτια
                  <span className="mx-2">•</span>
                  <span className="font-semibold">Άκυρα:</span> {voidVotes}
                  <span className="mx-2">•</span>
                  <span className="font-semibold">Λευκά:</span> {blankVotes}
                </div>
                {counted > totalVotes && (
                  <p className="text-sm text-red-600 font-semibold mt-1">Προειδοποίηση: Οι καταμετρημένες ψήφοι υπερβαίνουν το σύνολο των ψηφοδελτίων!</p>
                )}
              </div>
              <button
                className="px-6 py-2 rounded-full bg-slate-200 text-slate-700 font-semibold hover:bg-slate-300 transition-colors"
                onClick={() => setSetup(true)}
              >
                Πίσω στις ρυθμίσεις
              </button>
            </div>

            <div className="grid md:grid-cols-3 gap-6">
              <div className="flex items-center justify-between p-4 rounded-xl border-2 border-yellow-200 bg-yellow-50 shadow-sm">
                <div className="font-medium text-yellow-800">Άκυρα</div>
                <div className="flex items-center gap-3">
                  <button className="px-3 py-1 rounded-full bg-slate-200 text-slate-700 font-bold hover:bg-slate-300" onClick={() => setVoid(v => Math.max(0, v - 1))}>−</button>
                  <input className="w-24 text-center border-2 border-yellow-200 rounded-lg p-2 bg-yellow-100" type="number" value={voidVotes} onChange={e => setVoid(Math.max(0, +e.target.value || 0))} />
                  <button className="px-3 py-1 rounded-full bg-yellow-800 text-white font-bold hover:bg-yellow-900" onClick={() => setVoid(v => v + 1)}>+</button>
                </div>
              </div>
              <div className="flex items-center justify-between p-4 rounded-xl border-2 border-purple-200 bg-purple-50 shadow-sm">
                <div className="font-medium text-purple-800">Λευκά</div>
                <div className="flex items-center gap-3">
                  <button className="px-3 py-1 rounded-full bg-slate-200 text-slate-700 font-bold hover:bg-slate-300" onClick={() => setBlank(v => Math.max(0, v - 1))}>−</button>
                  <input className="w-24 text-center border-2 border-purple-200 rounded-lg p-2 bg-purple-100" type="number" value={blankVotes} onChange={e => setBlank(Math.max(0, +e.target.value || 0))} />
                  <button className="px-3 py-1 rounded-full bg-purple-800 text-white font-bold hover:bg-purple-900" onClick={() => setBlank(v => v + 1)}>+</button>
                </div>
              </div>
              <div className="flex items-center justify-between p-4 rounded-xl border-2 border-blue-200 bg-blue-50 shadow-sm">
                <div className="font-medium text-blue-800">Μέτρο ψήφων</div>
                <div className="font-bold text-lg text-blue-800">
                  {voteQuota > 0 ? voteQuota.toFixed(2) : '0.00'}
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <AnimatePresence>
                {parties.map((p, i) => {
                  const partyTotal = parties.reduce((s, x) => s + Number(x.votes || 0), 0);
                  const pct = percent(Number(p.votes || 0), partyTotal);
                  const proj = seatsNow[i] || 0;
                  const sec = securedSeats[i] || 0;
                  const remainder = voteQuota > 0 ? ((Number(p.votes || 0) / voteQuota) % 1).toFixed(2) : "0.00";
                  const neededVotes = voteQuota > 0 ? (voteQuota - (Number(p.votes || 0) % voteQuota)).toFixed(2) : "0.00";

                  return (
                    // The key is now on the party block itself, not the nested element.
                    // This allows the layout transition to work correctly.
                    <motion.div
                      key={i}
                      layout
                      initial={{ opacity: 0, y: -20, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: 20, scale: 0.95 }}
                      transition={{ duration: 0.3 }}
                      className="flex flex-col sm:flex-row items-center justify-between gap-4 p-4 rounded-xl border border-slate-200 shadow-sm"
                      style={{ backgroundColor: p.color + '15' }}
                    >
                      <div className="flex-grow">
                        <div className="font-semibold text-xl" style={{ color: p.color }}>{p.name || `Ψηφοδέλτιο ${i + 1}`}</div>
                        <div className="text-sm text-slate-600">
                          <span className="font-semibold">Ψήφοι %: {isFinite(pct) ? pct.toFixed(1) : "0.0"}%</span>
                          <span className="mx-2 sm:mx-4">•</span>
                          <span className="font-semibold">Υπόλοιπο: {remainder}</span>
                        </div>
                      </div>

                      {/* We're now using a single, keyed component to handle the transition */}
                      <AnimatePresence mode="wait">
                        {isFinalResult ? (
                          <motion.div
                            key="final"
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.8 }}
                            transition={{ duration: 0.5 }}
                            className="p-2 rounded-xl bg-slate-700 border-2 border-slate-500 w-full sm:w-64 h-24 flex flex-col items-center justify-center"
                          >
                            <div className="text-lg font-semibold text-white">Τελικές Έδρες</div>
                            <div className="text-4xl font-bold text-white ml-2">{proj}</div>
                          </motion.div>
                        ) : (
                          <motion.div
                            key="live"
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.8 }}
                            transition={{ duration: 0.5 }}
                            className="grid grid-cols-2 gap-2 w-full sm:w-auto text-center"
                          >
                            <div className="p-2 rounded-xl bg-blue-50 border-2 border-blue-200">
                              <div className="text-xs font-semibold text-blue-700">Προβλεπόμενες έδρες</div>
                              <div className="text-xl font-bold text-blue-900">{proj}</div>
                            </div>
                            <div className="p-2 rounded-xl bg-emerald-50 border-2 border-emerald-200">
                              <div className="text-xs font-semibold text-emerald-700">Εξασφαλισμένες έδρες</div>
                              <div className="text-xl font-bold text-emerald-900">{sec}</div>
                            </div>
                          </motion.div>
                        )}
                      </AnimatePresence>
                      
                      <div className="p-2 rounded-xl bg-orange-50 border-2 border-orange-200 text-center w-full sm:w-auto">
                        <div className="text-xs font-semibold text-orange-700">Ψήφοι για επόμενη έδρα</div>
                        <div className="text-xl font-bold text-orange-900">{neededVotes}</div>
                      </div>

                      <div className="flex items-center gap-2 w-full sm:w-auto">
                        <button className="px-4 py-2 rounded-lg bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition-colors w-1/2 sm:w-auto" onClick={() => updateParty(i, "votes", Math.max(0, Number(p.votes || 0) - 1))}>−</button>
                        <input className="w-full text-center border border-slate-300 rounded-lg p-2 font-mono" type="number" value={p.votes} onChange={e => updateParty(i, "votes", Math.max(0, +e.target.value || 0))} />
                        <button className="px-4 py-2 rounded-lg bg-slate-800 text-white font-bold hover:bg-slate-900 transition-colors w-1/2 sm:w-auto" onClick={() => updateParty(i, "votes", Number(p.votes || 0) + 1)}>+</button>
                      </div>
                    </motion.div>
                  );
                })}
              </AnimatePresence>
            </div>

            <motion.div
              layout
              className="w-full h-96 p-4 rounded-2xl bg-slate-50 shadow-inner"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.5, duration: 0.5 }}
            >
              <h2 className="text-xl font-bold mb-4 text-center">Κατανομή εδρών</h2>
              <ResponsiveContainer width="100%" height="90%">
                <BarChart data={parties.map((p, i) => {
                  const partyTotal = parties.reduce((s, x) => s + Number(x.votes || 0), 0);
                  const pct = percent(Number(p.votes || 0), partyTotal);
                  return { name: p.name || `Ψηφοδέλτιο ${i + 1}`, votes: Number(p.votes || 0), percent: isFinite(pct) ? pct.toFixed(1) : "0.0", seats: seatsNow[i] || 0, color: p.color };
                })}>
                  <XAxis
                    dataKey="name"
                    angle={-45}
                    textAnchor="end"
                    height={60}
                    tick={{ fontSize: 12 }}
                  />
                  <YAxis />
                  <Tooltip
                    formatter={(v, n) => n === "votes" ? `${v} ψήφοι` : (n === "percent" ? `${v}%` : `${v} έδρες`)}
                    contentStyle={{
                      borderRadius: '12px',
                      border: '1px solid #e5e7eb',
                      boxShadow: '0 4px 12px rgba(0,0,0,0.05)'
                    }}
                  />
                  <Bar dataKey="seats" name="Έδρες">
                    {parties.map((p, i) => (
                      <Cell key={i} fill={p.color} radius={[4, 4, 0, 0]} />
                    ))}
                    <LabelList
                      dataKey="percent"
                      position="insideTop"
                      formatter={(v) => `${v}%`}
                      style={{ fontSize: 12, fill: '#4b5563', fontWeight: 600 }}
                    />
                    <LabelList
                      dataKey="seats"
                      position="top"
                      style={{ fontSize: 14, fill: '#1f2937', fontWeight: 700 }}
                    />
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

